server {
    listen 443 ssl;
    server_name api.example.com;

    ssl_certificate         /etc/pki/api/server.pem;
    ssl_certificate_key     /etc/pki/api/server.key;
    ssl_protocols           TLSv1.2 TLSv1.3;

    # Trust only our internal client CA
    ssl_client_certificate  /etc/pki/ca/client-ca-chain.pem;
    ssl_verify_client       on;
    ssl_verify_depth        2;
    ssl_crl                 /etc/pki/ca/client-ca.crl;

    location / {
        proxy_set_header X-Client-DN $ssl_client_s_dn;
        proxy_set_header X-Client-Verify $ssl_client_verify;
        proxy_pass http://127.0.0.1:8080;
    }
}

